#include <bits/stdc++.h>
using namespace std;
int main(){
    int T; cin>>T;
    while(T--){
        int N; cin>>N;
        vector<vector<int>> milk(N);
        vector<char> alive(N,1);
        for(int i=0;i<N;i++){
            int Ti; cin>>Ti;
            milk[i].resize(Ti);
            for(int j=0;j<Ti;j++) cin>>milk[i][j];
        }
        int aliveCount = N;
        long long day = 0, lastEatenDay = 0, sinceLast = 0;
        const long long WINDOW = 2520;
        while(aliveCount>0 && sinceLast<WINDOW){
            day++; sinceLast++;
            int minVal=INT_MAX, minIdx=-1; bool tie=false;
            for(int i=0;i<N;i++){
                if(!alive[i]) continue;
                int Ti=(int)milk[i].size();
                int val = milk[i][(day-1)%Ti];
                if(val<minVal){ minVal=val; minIdx=i; tie=false; }
                else if(val==minVal) tie=true;
            }
            if(!tie && minIdx!=-1){
                alive[minIdx]=0; aliveCount--; lastEatenDay=day; sinceLast=0;
            }
        }
        cout << aliveCount << " " << lastEatenDay << "\n";
    }
}

